r Claim Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/commercial-hoa-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Wind Damage Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/tornado-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam, Freeze & Snow-Load Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/ice-dam-freeze-snow-load-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Farm & Outbuilding Appraisal","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/farm-outbuilding-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Umpire Services","url":"https://indianainsuranceappraiser.com/indiana-claim-appraisal/appraisal-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Tornado and wind claims","Ice dams and snow load"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://indianainsuranceappraiser.com/#website","url":"https://indianainsuranceappraiser.com/","name":"Indiana Insurance Appraiser","publisher":{"@id":"https://indianainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#webpage","url":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/","name":"Insurance Appraisal Glossary | ACV, RCV, Umpire","description":"Searchable insurance appraisal glossary: plain-English definitions of ACV, RCV, depreciation, umpire, ice dams, O&P and 30-plus more terms.","inLanguage":"en-US","isPartOf":{"@id":"https://indianainsuranceappraiser.com/#website"},"about":{"@id":"https://indianainsuranceappraiser.com/#business"},"publisher":{"@id":"https://indianainsuranceappraiser.com/#business"},"dateModified":"2026-11-17","primaryImageOfPage":{"@type":"ImageObject","@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#primaryimage","url":"https://indianainsuranceappraiser.com/assets/img/photos/calculator.webp","width":960,"height":640},"breadcrumb":{"@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#breadcrumb"},"mainEntity":{"@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://indianainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal glossary","item":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/"}],"@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance appraisal glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"The value of damaged property at the time of loss, usually replacement cost minus depreciation."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for increased living costs, such as temporary housing, while a home is uninhabitable after a covered loss."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It’s the question an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition allowing either party to demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Bad faith","description":"A legal claim that an insurer breached its duty of good faith and fair dealing. It’s decided by courts, not appraisal panels."},{"@type":"DefinedTerm","name":"Collapse","description":"A coverage provision, often narrow, for the abrupt falling down of a building or part of it from specified causes such as the weight of ice or snow."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy provision that reduces payment if the property was insured below a required percentage of its value."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy, for the house itself."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, for detached garages, sheds, fences and similar structures."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, property, limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value due to age, wear and obsolescence, used to calculate actual cash value."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm with damaging straight-line winds, such as the June 2012 event that crossed Indiana."},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing installed along roof edges to direct water into gutters; often missing from roof estimates."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage."},{"@type":"DefinedTerm","name":"Estimate review","description":"A professional line-by-line comparison of the carrier’s estimate with the actual damage and current pricing."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering underlayment applied at eaves and valleys to resist leaks from ice dams and wind-driven rain."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at a roof’s edge that traps meltwater, which can back up under shingles and into the home."},{"@type":"DefinedTerm","name":"Indiana Department of Insurance","description":"The state agency that regulates insurers, agents and adjusters in Indiana and handles consumer complaints."},{"@type":"DefinedTerm","name":"Indiana FAIR Plan","description":"The residual market association that provides basic property insurance to owners unable to obtain it in the regular market."},{"@type":"DefinedTerm","name":"Like kind and quality","description":"The standard for replacement materials that are similar in type and quality to the damaged property."},{"@type":"DefinedTerm","name":"Matching","description":"Whether replacement materials must reasonably match undamaged areas, a frequent issue with discontinued shingles and siding."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping a roof or drying a wet basement."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added repair costs required by building codes or ordinances in effect at the time of repair."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for coordinating and supervising repairs, often 10% and 10%."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which the insurer may request within a time set by the policy."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"The depreciation held back from an initial payment that a replacement cost policy pays after repairs are completed."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with like kind and quality, without deduction for depreciation."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full list of damaged items and repairs needed, before pricing."},{"@type":"DefinedTerm","name":"Square (roofing)","description":"One hundred square feet of roof surface."},{"@type":"DefinedTerm","name":"Steep charge","description":"An estimate line item that compensates for slower work on steep roofs, commonly starting around 7/12 pitch."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy provision setting how long the insured has to file a lawsuit, commonly two years in Indiana property policies."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an existing claim estimate, usually supported by documentation."},{"@type":"DefinedTerm","name":"Test square","description":"A marked 10-by-10-foot area on a roof slope used to count hail impacts."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Unfair claim settlement practices","description":"Claim-handling conduct prohibited by Indiana insurance law and enforced by the Department of Insurance."},{"@type":"DefinedTerm","name":"Water backup endorsement","description":"Optional coverage for water that backs up through sewers or drains or overflows from a sump, usually with its own limit."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property repairs by ZIP code."}],"@id":"https://indianainsuranceappraiser.com/insurance-appraisal-terms/#definedtermset"}]}</script>
